namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Code { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public int DepartmentId { get; set; }
    public string CourseCode { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Full name is required.")]
    [StringLength(100, ErrorMessage = "Name must be 100 characters or fewer.")]
    public string FullName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Za-z0-9\-]+$", ErrorMessage = "Student ID must contain only letters, numbers, and hyphens.")]
    [StringLength(20, ErrorMessage = "Student ID must be 20 characters or fewer.")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Code = "ENG", Name = "English", Description = "Study of literature, writing, and communication." },
            new() { Id = 4, Code = "PHYS", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "Study of past events, societies, and civilizations." },
        };

        _courses = new List<Course>
        {
            // Computer Science
            new() { Id = 1, DepartmentId = 1, CourseCode = "CS 101", Title = "Introduction to Computer Science", Description = "A broad introduction to computer science covering computational thinking, basic programming in Python, data representation, and an overview of how computers work. No prior experience required.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Ada Lovelace", InstructorBio = "Dr. Lovelace holds a Ph.D. in Computer Science from MIT and has over 15 years of teaching experience. Her research focuses on programming language design and CS education.", IsFeatured = true },
            new() { Id = 2, DepartmentId = 1, CourseCode = "CS 201", Title = "Data Structures and Algorithms", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs, hash tables) and algorithm design techniques (sorting, searching, dynamic programming). Emphasis on time and space complexity analysis.", Credits = 4, Schedule = "Tue/Thu 10:30 AM–12:00 PM", InstructorName = "Dr. Alan Turing", InstructorBio = "Dr. Turing is a distinguished professor whose work on computational complexity has been published in top-tier journals. He brings practical industry experience from his years at a major tech company.", IsFeatured = false },
            new() { Id = 3, DepartmentId = 1, CourseCode = "CS 310", Title = "Database Systems", Description = "Design and implementation of relational database systems. Covers SQL, normalization, transaction management, indexing, and an introduction to NoSQL databases.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", InstructorName = "Dr. Edgar Codd", InstructorBio = "Dr. Codd is an expert in database theory with 20 years of research and industry experience. He has contributed to several open-source database projects.", IsFeatured = false },
            new() { Id = 4, DepartmentId = 1, CourseCode = "CS 450", Title = "Machine Learning", Description = "Introduction to machine learning concepts including supervised and unsupervised learning, neural networks, and model evaluation. Students complete a hands-on project using real-world datasets.", Credits = 4, Schedule = "Tue/Thu 1:00–2:30 PM", InstructorName = "Dr. Ada Lovelace", InstructorBio = "Dr. Lovelace holds a Ph.D. in Computer Science from MIT and has over 15 years of teaching experience. Her research focuses on programming language design and CS education.", IsFeatured = true },

            // Mathematics
            new() { Id = 5, DepartmentId = 2, CourseCode = "MATH 101", Title = "Calculus I", Description = "Introduction to differential calculus covering limits, continuity, derivatives, and their applications. Prepares students for Calculus II and applied mathematics courses.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Emmy Noether", InstructorBio = "Dr. Noether is an award-winning mathematics professor specializing in abstract algebra and theoretical physics. She is known for her engaging lectures and commitment to student success.", IsFeatured = true },
            new() { Id = 6, DepartmentId = 2, CourseCode = "MATH 201", Title = "Linear Algebra", Description = "Study of vector spaces, matrices, linear transformations, eigenvalues, and eigenvectors. Essential for students in mathematics, physics, engineering, and computer science.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", InstructorName = "Dr. Carl Gauss", InstructorBio = "Dr. Gauss is a professor of applied mathematics with extensive experience in numerical methods and scientific computing.", IsFeatured = false },
            new() { Id = 7, DepartmentId = 2, CourseCode = "MATH 310", Title = "Probability and Statistics", Description = "Fundamentals of probability theory, random variables, distributions, hypothesis testing, and regression analysis. Includes practical exercises with statistical software.", Credits = 3, Schedule = "Mon/Wed 1:00–2:20 PM", InstructorName = "Dr. Emmy Noether", InstructorBio = "Dr. Noether is an award-winning mathematics professor specializing in abstract algebra and theoretical physics. She is known for her engaging lectures and commitment to student success.", IsFeatured = false },

            // English
            new() { Id = 8, DepartmentId = 3, CourseCode = "ENG 101", Title = "English Composition", Description = "Develop core writing skills through essays, research papers, and peer review. Focuses on clarity, argumentation, and proper citation practices.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Prof. Virginia Woolf", InstructorBio = "Prof. Woolf is a published author and writing instructor with a passion for helping students find their voice. She holds an MFA from the Iowa Writers' Workshop.", IsFeatured = false },
            new() { Id = 9, DepartmentId = 3, CourseCode = "ENG 220", Title = "American Literature", Description = "Survey of major works and movements in American literature from the colonial period to the present. Authors include Hawthorne, Twain, Fitzgerald, Morrison, and others.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", InstructorName = "Dr. James Baldwin", InstructorBio = "Dr. Baldwin is a literary scholar specializing in American and African-American literature. His essays on cultural criticism have appeared in numerous academic journals.", IsFeatured = true },

            // Physics
            new() { Id = 10, DepartmentId = 4, CourseCode = "PHYS 101", Title = "General Physics I", Description = "Introduction to mechanics, thermodynamics, and waves. Includes weekly lab sessions reinforcing lecture concepts through hands-on experiments.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Thu Lab 3:00–5:00 PM", InstructorName = "Dr. Richard Feynman", InstructorBio = "Dr. Feynman is a charismatic physics professor known for making complex topics accessible. His research spans quantum electrodynamics and nanotechnology.", IsFeatured = false },
            new() { Id = 11, DepartmentId = 4, CourseCode = "PHYS 250", Title = "Modern Physics", Description = "Covers special relativity, quantum mechanics, atomic structure, and nuclear physics. Builds on General Physics I and Calculus I prerequisites.", Credits = 3, Schedule = "Tue/Thu 2:00–3:20 PM", InstructorName = "Dr. Marie Curie", InstructorBio = "Dr. Curie is a renowned physicist whose experimental research in radioactivity has earned international recognition. She is dedicated to mentoring the next generation of scientists.", IsFeatured = true },

            // History
            new() { Id = 12, DepartmentId = 5, CourseCode = "HIST 101", Title = "World History to 1500", Description = "Survey of major civilizations, cultures, and events from antiquity through the late medieval period. Examines political, social, and economic developments across continents.", Credits = 3, Schedule = "Mon/Wed 10:00–11:20 AM", InstructorName = "Dr. Howard Zinn", InstructorBio = "Dr. Zinn is a historian and author focused on social movements and people's history. His interdisciplinary approach makes history accessible and relevant.", IsFeatured = false },
            new() { Id = 13, DepartmentId = 5, CourseCode = "HIST 320", Title = "The Civil Rights Movement", Description = "In-depth study of the American civil rights movement from the 1950s to 1970s. Analyzes key figures, landmark legislation, grassroots activism, and lasting impacts on American society.", Credits = 3, Schedule = "Tue/Thu 3:30–4:50 PM", InstructorName = "Dr. Howard Zinn", InstructorBio = "Dr. Zinn is a historian and author focused on social movements and people's history. His interdisciplinary approach makes history accessible and relevant.", IsFeatured = false },
        };
    }

    public List<Department> GetAllDepartments() => _departments;

    public Department? GetDepartmentById(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetAllCourses() => _courses;

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourseById(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList();

    public List<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public string? GetDepartmentName(int departmentId) =>
        _departments.FirstOrDefault(d => d.Id == departmentId)?.Name;
}

