 @page "/enroll"
 @inject CatalogService Catalog
 @inject NavigationManager Navigation

 <PageTitle>Enrollment Request</PageTitle>

 <h1>Enrollment Request</h1>
 <p>Fill out the form below to submit an enrollment request.</p>

 @if (Submitted)
 {
     <div class="alert alert-success">
         <h4>Request Submitted</h4>
         <p>Thank you, <strong>@Model.FullName</strong>. Your enrollment request for
             <strong>@(Catalog.GetCourseById(Model.CourseId)?.Title ?? "the selected course")</strong>
             has been received. You will receive a confirmation via your university email.</p>
         <a href="enroll" class="btn btn-outline-primary mt-2">Submit Another Request</a>
         <a href="" class="btn btn-outline-secondary mt-2 ms-2">Return Home</a>
     </div>
 }
 else
 {
     <EditForm method="post" Model="Model" OnValidSubmit="HandleSubmit" FormName="enrollment">
         <DataAnnotationsValidator />
         <ValidationSummary class="text-danger" />

         <div class="mb-3">
             <label for="fullName" class="form-label">Full Name</label>
             <InputText id="fullName" class="form-control" @bind-Value="Model.FullName" />
             <ValidationMessage For="() => Model.FullName" class="text-danger" />
         </div>

         <div class="mb-3">
             <label for="studentId" class="form-label">Student ID</label>
             <InputText id="studentId" class="form-control" @bind-Value="Model.StudentId" />
             <ValidationMessage For="() => Model.StudentId" class="text-danger" />
         </div>

         <div class="mb-3">
             <label for="courseId" class="form-label">Course</label>
             <InputSelect id="courseId" class="form-select" @bind-Value="Model.CourseId">
                 <option value="0">— Select a course —</option>
                 @foreach (var course in Catalog.GetAllCourses())
                 {
                     <option value="@course.Id">@course.CourseCode — @course.Title</option>
                 }
             </InputSelect>
             <ValidationMessage For="() => Model.CourseId" class="text-danger" />
         </div>

         <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
         <a href="courses" class="btn btn-outline-secondary ms-2">Browse Courses</a>
     </EditForm>
 }

